/*
 ******************************************************************************
 * @file           : clips_voz.c
 * @author         : Juan Jose Giraldo Arbelaez
 * @brief          : Datos de audio de las tres palabras de confirmación
 ******************************************************************************
 *
 *  ┌──────────────────────────────────────────────────────────────────────┐
 *  │  ESTE ARCHIVO ES UNA PLANTILLA. Sustituya los tres arreglos de       │
 *  │  ejemplo por los que emitió la grabadora al pulsar 'd', renombrando  │
 *  │  cada 'clip_XXX' por clip_uno, clip_dos o clip_tres según la palabra │
 *  │  que corresponda.                                                    │
 *  └──────────────────────────────────────────────────────────────────────┘
 *
 * Los arreglos de ejemplo contienen un breve pitido en lugar de voz, de modo
 * que el proyecto compile y funcione antes de pegar las grabaciones reales:
 * así se puede verificar la lógica del encoder de forma independiente del
 * audio grabado. Al oír pitidos en vez de palabras, la sustitución sigue
 * pendiente.
 *
 * Formato de los datos: muestras de 16 bits con signo a 16 kHz, mono.
 ******************************************************************************
 */

